def now():
    return datetime.datetime.now(JST).isoformat()


def sha_bytes(b):
    return hashlib.sha256(b).hexdigest()


def sha_file(p):
    with open(p, 'rb') as f:
        return hashlib.file_digest(f, 'sha256').hexdigest()


def tree_sha(root):
    return {str(p.relative_to(root)): sha_file(p) for p in sorted(root.rglob('*')) if p.is_file()}


def find_p92c(explicit):
    """Locate p92c by size + SHA-256 only; the file name (e.g. 'p92c(1) (1).zip') is irrelevant."""
    candidates = [Path(explicit)] if explicit else []
    for base, pattern in [(Path('/content'), '*.zip'), (Path.cwd(), '*.zip'),
                          (Path('/content/drive/MyDrive'), '*.zip'), (Path('/content/drive/MyDrive'), '*/*.zip')]:
        if base.is_dir():
            candidates += sorted(base.glob(pattern))
    for p in candidates:
        try:
            if p.is_file() and p.stat().st_size == P92C_SIZE and sha_file(p) == P92C_SHA:
                return p.read_bytes(), str(p)
        except OSError:
            continue
    try:
        from google.colab import files
    except ImportError:
        raise SystemExit('STOP: p92c(1).zip (sha ' + P92C_SHA[:12] + '…) not found; pass --p92c PATH')
    print('P104_SELECT_P92C_ZIP (any file name is accepted; verified by SHA-256)', flush=True)
    uploaded = files.upload()
    for name, data in uploaded.items():
        if len(data) == P92C_SIZE and sha_bytes(data) == P92C_SHA:
            return data, 'uploaded:' + name
    raise SystemExit('STOP: P92C_BUNDLE_SHA_MISMATCH for uploaded ' + ', '.join(uploaded))


def extract_verified(bundle, work):
    with zipfile.ZipFile(io.BytesIO(bundle)) as outer:
        assert outer.testzip() is None, 'OUTER_ZIP_CRC_FAILED'
        srcbytes = outer.read('source/PAI92_source.zip')
    assert sha_bytes(srcbytes) == SOURCE_ZIP_SHA, 'SOURCE_ZIP_SHA_MISMATCH'
    source_dir = work / 'source'
    source_dir.mkdir()
    with zipfile.ZipFile(io.BytesIO(srcbytes)) as z:
        assert z.testzip() is None, 'SOURCE_ZIP_CRC_FAILED'
        for member in z.infolist():
            parts = Path(member.filename).parts
            if member.filename.startswith('/') or '..' in parts:
                raise RuntimeError('UNSAFE_ZIP_PATH')
            target = source_dir / member.filename
            if member.is_dir():
                target.mkdir(parents=True, exist_ok=True)
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(z.read(member))
    # Same 17-photo restoration as the Stage99 notebook (cell 1), byte-verified.
    m = json.loads((source_dir / 'realphoto/asset_swap_manifest.json').read_text('utf8'))
    assert m['original_real_photos_count'] == 17
    photos = source_dir / 'realphoto/original_images'
    photos.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(source_dir / 'REAL17_USER_SOURCE_17.zip') as original:
        assert original.testzip() is None
        assert set(original.namelist()) == set(m['original_photo_sha256'])
        for fname, expected in m['original_photo_sha256'].items():
            raw = original.read(fname)
            assert sha_bytes(raw) == expected, 'PHOTO_HASH_MISMATCH ' + fname
            (photos / fname).write_bytes(raw)
    for rel, meta in m['replaced_assets'].items():
        assert sha_file(source_dir / rel) == meta['real_photo_sha256'], 'REPLACED_ASSET_HASH_MISMATCH ' + rel
    return source_dir


def apply_stage104_state(source_dir):
    """Stage99 9/10 bytes + the Stage103 candidate stage90; refuse anything else."""
    s84 = source_dir / 'stage88/stage84_camera_ai.py'
    s90 = source_dir / 'stage88/stage90_wound_evidence.py'
    runner = source_dir / 'stage88/run_stage70_continuous.py'
    assets = source_dir / 'stage88/stage58_apple_photo_assets/prepared/uv_photo_front'
    c1_src = source_dir / 'REAL17_POLAR_COMPOSITE_11/判定C-1_POLAR_COMPOSITE_UV.png'
    assert sha_file(s84) == STAGE84_ORIGINAL, 'STAGE84_NOT_ORIGINAL_P92C'
    assert sha_file(s90) == STAGE90_P99, 'STAGE90_NOT_STAGE99_BASELINE'
    assert sha_file(runner) == RUNNER, 'RUNNER_NOT_BASELINE'
    assert sha_file(c1_src) == C1_UV, 'C1_SOURCE_UV_MISMATCH'
    assert sha_file(assets / '05_C_uv.png') == C3_UV, 'BASE_C3_TEX_SHA_MISMATCH'
    assert not (assets / '10_C1_uv.png').exists(), 'PARTIAL_STAGE99_STATE'
    assert sha_bytes(STAGE84_P99_BYTES) == STAGE84_P99, 'EMBEDDED_STAGE84_CORRUPT'
    assert sha_bytes(STAGE90_P99_BYTES) == STAGE90_P99, 'EMBEDDED_STAGE90_P99_CORRUPT'
    assert sha_bytes(STAGE90_CANDIDATE_BYTES) == STAGE90_CANDIDATE, 'EMBEDDED_CANDIDATE_CORRUPT'
    assert s90.read_bytes() == STAGE90_P99_BYTES
    cand = STAGE90_CANDIDATE_BYTES.decode('utf-8')
    required = ['0.20*w<=x and x+bw<=0.80*w and', 'chroma_ratio<=0.75', 'redness_drop>=3.0', 'texture>=7.0',
                'if not proof:', '0.45<bw/max(1,bh)<2.8', 'if contrast<13: continue']
    assert all(cand.count(r) == 1 for r in required), 'CANDIDATE_GATES_INCOMPLETE'
    assert '1.10<=bw/max(1,bh)' not in cand and 'contrast<28' not in cand, 'STAGE102_ASPECT_PATCH_PRESENT'
    s84.write_bytes(STAGE84_P99_BYTES)
    shutil.copyfile(c1_src, assets / '10_C1_uv.png')
    s90.write_bytes(STAGE90_CANDIDATE_BYTES)
    after = {'stage84': sha_file(s84), 'stage90': sha_file(s90), 'runner': sha_file(runner),
             '10_C1_uv.png': sha_file(assets / '10_C1_uv.png'), '05_C_uv.png': sha_file(assets / '05_C_uv.png')}
    assert after == {'stage84': STAGE84_P99, 'stage90': STAGE90_CANDIDATE, 'runner': RUNNER,
                     '10_C1_uv.png': C1_UV, '05_C_uv.png': C3_UV}, 'STAGE104_STATE_MISMATCH'
    diff = ''.join(difflib.unified_diff(
        STAGE90_P99_BYTES.decode('utf-8').splitlines(True), cand.splitlines(True),
        'stage90_wound_evidence.py (Stage99 37f1e756)', 'stage90_wound_evidence.py (Stage104 dd5c008c)'))
    return after, diff


def check_against_pristine(pristine, patched):
    changed = sorted(k for k in pristine if k in patched and pristine[k] != patched[k])
    added = sorted(k for k in patched if k not in pristine)
    removed = sorted(k for k in pristine if k not in patched)
    ok = (changed == ['stage88/stage84_camera_ai.py', 'stage88/stage90_wound_evidence.py'] and
          added == ['stage88/stage58_apple_photo_assets/prepared/uv_photo_front/10_C1_uv.png'] and not removed)
    return ok, {'changed': changed, 'added': added, 'removed': removed,
                'only_stage84_stage99_and_stage90_candidate_and_c1_uv': ok}


def preflight(source_dir, work):
    """Fonts + dependencies before any physics. Fails closed."""
    rep = {}
    if not any(Path(p).is_file() for p in CJK_FONTS):
        subprocess.run(['apt-get', 'update', '-qq'], check=True)
        subprocess.run(['apt-get', 'install', '-y', '-qq', 'fonts-noto-cjk'], check=True)
    font = next((p for p in CJK_FONTS if Path(p).is_file()), None)
    if font is None:
        raise SystemExit('STOP: P104_CJK_FONT_MISSING_AFTER_INSTALL')
    rep['cjk_font'] = font
    req = source_dir / 'stage88/requirements.txt'
    pip = subprocess.run([sys.executable, '-m', 'pip', 'install', '-q', '-r', str(req)],
                         capture_output=True, text=True, errors='replace')
    rep['pip_install_rc'] = pip.returncode
    if pip.returncode:
        raise SystemExit('STOP: P104_PIP_INSTALL_FAILED ' + pip.stderr[-2000:])
    probe = r'''
import json, sys
from PIL import ImageFont
out = {'python': sys.version.split()[0]}
f = ImageFont.truetype(sys.argv[1], 160); b = f.getbbox('判定 C')
out['cjk_glyph_width_px'] = b[2] - b[0]
import sklearn, pybullet, numpy, cv2, trimesh, joblib, imageio, imageio_ffmpeg, matplotlib
out.update(sklearn=sklearn.__version__, numpy=numpy.__version__, opencv=cv2.__version__,
           imageio=imageio.__version__, trimesh=trimesh.__version__, matplotlib=matplotlib.__version__)
out['ffmpeg_exe'] = imageio_ffmpeg.get_ffmpeg_exe()
c = pybullet.connect(pybullet.DIRECT); out['pybullet_api'] = pybullet.getAPIVersion(); pybullet.disconnect(c)
print(json.dumps(out))
'''
    p = subprocess.run([sys.executable, '-c', probe, font], capture_output=True, text=True, errors='replace')
    if p.returncode:
        raise SystemExit('STOP: P104_DEPENDENCY_PROBE_FAILED ' + p.stderr[-2000:])
    rep.update(json.loads(p.stdout.strip().splitlines()[-1]))
    ok = rep['sklearn'] == '1.8.0' and rep['cjk_glyph_width_px'] > 170 and Path(rep['ffmpeg_exe']).is_file()
    rep['preflight_pass'] = bool(ok)
    (work / 'P104_PREFLIGHT.json').write_text(json.dumps(rep, ensure_ascii=False, indent=1), 'utf8')
    if not ok:
        raise SystemExit('STOP: P104_PREFLIGHT_FAILED ' + json.dumps(rep, ensure_ascii=False))
    print('P104_PREFLIGHT_PASS', json.dumps(rep, ensure_ascii=False), flush=True)
    return rep


def run_physics(source_dir, work, hook_dir, capture_dir):
    env = os.environ.copy()
    env.update(STAGE89_REAL_WOUND_GATE='1', STAGE90_DAMAGE_EVIDENCE='1',
               STAGE92_FIXED_MOUNT='1', STAGE99_CASE10_C1_UV='1',
               STAGE92_THREE_CASES='0', STAGE91_MOUNT_GRID_DIAGNOSTIC='0')
    env.pop('STAGE84_SMALL_SCAR_DEMO', None)
    env.pop('STAGE76_C_EXTRA_PHOTOS', None)
    env['PAI103_CAPTURE_DIR'] = str(capture_dir)
    env['PYTHONPATH'] = str(hook_dir) + (os.pathsep + env['PYTHONPATH'] if env.get('PYTHONPATH') else '')
    result_dir = work / 'P104_RESULTS'
    cmd = [sys.executable, '-u', str(source_dir / 'run_realphoto_full10.py'),
           '--repo', str(source_dir), '--out', str(result_dir), '--install']
    print('RUN_PHYSICS_FULL10_STAGE104', cmd, flush=True)
    log = (work / 'P104_RUNTIME.log').open('w', encoding='utf-8')
    p = subprocess.Popen(cmd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                         text=True, errors='replace', bufsize=1)
    for line in p.stdout:
        print(line, end='', flush=True)
        log.write(line)
    rc = p.wait()
    log.close()
    print('RUNNER_RETURN_CODE', rc, flush=True)
    return rc, result_dir


def validate_capture(capture_dir):
    """Completeness + 'saving changed nothing' evidence. Returns (ok, report)."""
    rep = {'hook_active': (capture_dir / 'hook_active.json').is_file(),
           'hook_errors': (capture_dir / 'hook_errors.jsonl').read_text('utf8').splitlines()
           if (capture_dir / 'hook_errors.jsonl').is_file() else [],
           'patched_modules': [json.loads(l)['module'] for l in
                               (capture_dir / 'hook_patched_modules.jsonl').read_text('utf8').splitlines()]
           if (capture_dir / 'hook_patched_modules.jsonl').is_file() else []}
    concludes = sorted(capture_dir.glob('conclude_*.json'))
    infers = sorted(capture_dir.glob('infer_*_input.json'))
    outs = sorted(capture_dir.glob('infer_*_output.json'))
    rep['conclude_records'] = len(concludes)
    rep['inference_records'] = len(infers)
    per_case = {}
    conclude_sets = {}
    unchanged = True
    for f in concludes:
        j = json.loads(f.read_text('utf8'))
        unchanged &= bool(j['frames_unchanged_by_saving'])
        counts = {}
        for r in j['frames']:
            mode = r['key'][0] if isinstance(r['key'], list) else 'other'
            counts[mode] = counts.get(mode, 0) + 1
            stored = capture_dir / 'frames' / r.get('file', '')
            if not stored.is_file():
                counts['MISSING_FILE'] = counts.get('MISSING_FILE', 0) + 1
        per_case[j['case_name']] = {'kind': j['kind'], 'counts': counts}
        conclude_sets[j['case_name']] = {(tuple(r['key']) if isinstance(r['key'], list) else r['key']):
                                         r['sha256_raw_bytes'] for r in j['frames']}
    infer_match = {}
    for f in infers:
        j = json.loads(f.read_text('utf8'))
        unchanged &= bool(j['frames_unchanged_by_saving'])
        keys = {(tuple(r['key']) if isinstance(r['key'], list) else r['key']): r['sha256_raw_bytes']
                for r in j['frames']}
        hits = [n for n, cs in conclude_sets.items() if all(cs.get(k) == v for k, v in keys.items())]
        infer_match[f.name] = hits
    for f in outs:
        unchanged &= bool(json.loads(f.read_text('utf8'))['frames_unchanged_by_inference'])
    rep['per_case_frame_counts'] = per_case
    rep['inference_input_matched_to_conclude_frames'] = infer_match
    rep['all_frames_unchanged_by_saving_and_inference'] = unchanged
    apples_complete = all(v['counts'].get('dense', 0) == 48 and v['counts'].get('finger', 0) == 12 and
                          v['counts'].get('palm', 0) >= 1 and v['counts'].get('bottom', 0) == 3 and
                          'MISSING_FILE' not in v['counts']
                          for v in per_case.values() if v['kind'] == 'apple')
    a_cases = [n for n in per_case if n.split('_')[0] in ('01', '06', '07', '08')]
    rep['A_cases_1_6_7_8_present'] = sorted(a_cases)
    ok = (rep['hook_active'] and not rep['hook_errors'] and
          sorted(rep['patched_modules']) == ['stage67_camera_ai', 'stage84_camera_ai'] and
          len(concludes) == 10 and len(infers) == 9 and unchanged and apples_complete and
          len(a_cases) == 4 and all(len(v) == 1 for v in infer_match.values()))
    rep['capture_complete'] = bool(ok)
    return ok, rep


def read_json(p):
    return json.loads(Path(p).read_text('utf8')) if Path(p).is_file() else None


def grade_run(rc, result_dir, capture_dir):
    """Inspect every case of the physical run against the post-run reference."""
    phys = result_dir / 'stage70_physics'
    status = read_json(result_dir / 'RUN_STATUS_REAL17.json') or {}
    summary = read_json(phys / 'summary.json') or {}
    exp = P104_REFERENCE['expected_after_patch']
    cases = {}
    failures = []
    for name, e in exp.items():
        r = read_json(phys / 'case_reports' / (name + '.json'))
        cc = read_json(phys / 'stage62_camera_cases' / (name + '.json')) or {}
        audit = read_json(phys / 'stage90_real_camera_damage' / (name + '_wound_audit.json'))
        if r is None:
            cases[name] = {'missing_case_report': True}
            failures.append(name + ': case report missing')
            continue
        cls = r['classification'].get('class') if isinstance(r['classification'], dict) else r['classification']
        inf = cc.get('inference') or {}
        ev = inf.get('stage90_severe_wound_evidence') or (audit or {}).get('severe_wound') or {}
        proof = ev.get('proof') or []
        kinds = sorted({p['kind'] for p in proof})
        wound = 'ROUND' if any('ROUND' in k for k in kinds) else ('LINEAR' if kinds else None)
        events = [x.get('event') if isinstance(x, dict) else x for x in (r.get('case_events') or [])]
        row = {'object': r.get('object'), 'ai_class': cls, 'decision_reason': inf.get('decision_reason'),
               'destination': r.get('destination'), 'pass': r.get('pass'),
               'physical_status': r.get('physical_status'), 'success_physical_and_ai': r.get('success_physical_and_ai'),
               'wound_evidence': wound, 'wound_proof': [{'kind': p['kind'], 'camera': p.get('camera'),
                                                         'frames': p.get('frames', p.get('frame')),
                                                         'bbox': [w.get('bbox_xyxy') for w in p.get('wounds', [])]}
                                                        for p in proof],
               'stop_resume_events': [x for x in events if x and any(
                   s in str(x).upper() for s in ('FULL_STOP', 'RESUME', 'REMOVED', 'TRANSFER', 'HOLD'))],
               'case_events': events, 'expected': e}
        checks = {'pass': r.get('pass') is True,
                  'class': cls == e['classification'],
                  'destination': r.get('destination') == e['destination'],
                  'wound_evidence': wound == e['wound_evidence']}
        if e.get('nonapple_reject'):
            checks['nonapple_rejected'] = r.get('object') != 'apple' and r.get('destination') is None
        row['checks'] = checks
        for k, v in checks.items():
            if not v:
                failures.append('%s: %s (got %r)' % (name, k, row.get({'class': 'ai_class'}.get(k, k))))
        cases[name] = row
    all_events = [x for v in cases.values() for x in v.get('case_events', [])]
    stop_resume = {'THREE_FULL_STOP': any('THREE_FULL_STOP' in str(x) for x in all_events),
                   'RESUME': any(str(x) == 'RESUME' for x in all_events)}
    if not all(stop_resume.values()):
        failures.append('stop/resume events missing: %r' % stop_resume)
    runner = {'runner_rc': rc, 'run_status_all_pass': status.get('all_pass'),
              'summary_all_pass': summary.get('all_pass'), 'n_episodes': summary.get('n_episodes'),
              'nonapple_safe_rejections': summary.get('stage70_safe_nonapple_rejections')}
    if not (rc == 0 and status.get('all_pass') is True and summary.get('all_pass') is True and
            summary.get('n_episodes') == 10):
        failures.append('runner verdict not ALL_PASS: %r' % runner)
    # Did the AI see the same pixels that the Stage103 regression validated?
    same_inputs = {}
    ref_inputs = P104_REFERENCE['p103_inference_input_frame_sha256']
    for f in sorted(capture_dir.glob('infer_*_input.json')):
        keys = {repr(tuple(r['key'])): r['sha256_raw_bytes']
                for r in read_json(f)['frames'] if isinstance(r['key'], list)}
        match = [n for n, ref in ref_inputs.items() if ref == keys]
        same_inputs[f.name] = match[0] if match else None
    identical = sorted(v for v in same_inputs.values() if v)
    return {'cases': cases, 'runner': runner, 'stop_resume': stop_resume,
            'scenario_coverage': summary.get('scenario_coverage'),
            'inference_inputs_identical_to_p103_validated': {
                'matched_cases': identical, 'all_9_identical': len(identical) == 9 and len(same_inputs) == 9},
            'failures': failures, 'all_10_verified': not failures}


def video_evidence(result_dir, work):
    """Keep the raw recording untouched; hash it, read metadata, split copies <19MB."""
    out = []
    parts_dir = work / 'P104_VIDEO_PARTS'
    for v in sorted((result_dir / 'stage70_physics').rglob('*.mp4')):
        meta = {}
        try:
            import imageio.v2 as imageio
            r = imageio.get_reader(str(v))
            m = r.get_meta_data()
            meta = {k: m.get(k) for k in ('fps', 'size', 'duration', 'codec')}
            r.close()
        except Exception as exc:
            meta = {'metadata_error': repr(exc)}
        parts = []
        if v.name == VIDEO_NAME:
            parts_dir.mkdir(exist_ok=True)
            data = v.read_bytes()
            step = VOLUME_LIMIT - 1
            n = (len(data) + step - 1) // step
            for i in range(n):
                pp = parts_dir / ('P104_%s.part%02dof%02d' % (v.name, i + 1, n))
                pp.write_bytes(data[i * step:(i + 1) * step])
                parts.append({'part': pp.name, 'bytes': pp.stat().st_size, 'sha256': sha_file(pp)})
        out.append({'path': str(v.relative_to(result_dir)), 'bytes': v.stat().st_size,
                    'sha256': sha_file(v), 'metadata': meta, 'byte_parts': parts})
    return out


VOLUME_LIMIT = 19_000_000   # bytes; every volume stays below 20 MB attachment limits


def collect_result_files(work, result_dir, capture_dir, extra):
    items = []
    phys = result_dir / 'stage70_physics'
    for f in extra:
        if f and f.is_file():
            items.append((f.name, f))
    for rel in ['RUN_STATUS_REAL17.json', 'EXECUTION_LOG.txt']:
        if (result_dir / rel).is_file():
            items.append((rel, result_dir / rel))
    for f in sorted(phys.glob('*')) if phys.is_dir() else []:
        if f.is_file() and f.suffix.lower() in ('.json', '.csv', '.txt'):
            items.append(('stage70_physics/' + f.name, f))
    for sub in ['case_reports', 'stage62_camera_cases', 'stage90_real_camera_damage',
                'stage99_case05_case10_camera', 'stage92_actual_camera', 'ai_camera']:
        d = phys / sub
        if d.is_dir():
            items += [('stage70_physics/' + str(f.relative_to(phys)), f) for f in sorted(d.rglob('*'))
                      if f.is_file() and f.suffix.lower() != '.mp4']
    if capture_dir.is_dir():
        items += [('pai104_capture/' + str(f.relative_to(capture_dir)), f)
                  for f in sorted(capture_dir.rglob('*')) if f.is_file()]
    return items


def write_volumes(items, out_dir, stem='P103_CAPTURE_RESULT', limit=VOLUME_LIMIT):
    """Self-contained zip volumes, each < limit bytes, plus a SHA-256 manifest.

    A file is moved to a new volume when the current volume plus the file's
    uncompressed size (an upper bound for its stored size) would reach limit.
    """
    margin = 64 * 1024   # local header + central directory allowance
    groups, cur, cur_size = [], [], 0
    for name, path in items:
        size = path.stat().st_size + len(name) * 2 + 200
        if size + margin >= limit:
            raise RuntimeError('SINGLE_FILE_TOO_LARGE_FOR_VOLUME ' + name)
        if cur and cur_size + size + margin >= limit:
            groups.append(cur)
            cur, cur_size = [], 0
        cur.append((name, path))
        cur_size += size
    if cur:
        groups.append(cur)
    n = len(groups)
    volumes = []
    for i, group in enumerate(groups, 1):
        vol = out_dir / ('%s_vol%02dof%02d.zip' % (stem, i, n))
        if vol.exists():
            vol.unlink()
        members = []
        with zipfile.ZipFile(vol, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=6) as z:
            for name, path in group:
                z.write(path, name)
                members.append({'name': name, 'sha256': sha_file(path), 'bytes': path.stat().st_size})
        with zipfile.ZipFile(vol) as z:
            assert z.testzip() is None, 'VOLUME_CRC_FAILED ' + vol.name
        size = vol.stat().st_size
        assert size < limit, ('VOLUME_TOO_LARGE', vol.name, size)
        volumes.append({'volume': vol.name, 'bytes': size, 'sha256': sha_file(vol), 'members': members})
    manifest = {'stage': 103, 'created_jst': now(), 'volume_limit_bytes': limit, 'volume_count': n,
                'total_members': sum(len(v['members']) for v in volumes), 'volumes': volumes,
                'how_to_use': 'attach every volume and this manifest; each volume is an independent zip'}
    mf = out_dir / ('%s_MANIFEST.json' % stem)
    mf.write_text(json.dumps(manifest, ensure_ascii=False, indent=1), 'utf8')
    return [out_dir / v['volume'] for v in volumes], mf


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument('--p92c')
    ap.add_argument('--work')
    a, _unknown = ap.parse_known_args(argv)  # Colab kernels pass extra argv
    print('PAI104_FINAL_PHYSICAL_RUN_START', now(), flush=True)
    bundle, origin = find_p92c(a.p92c)
    work = Path(a.work) if a.work else Path(tempfile.mkdtemp(prefix='PAI104_'))
    work.mkdir(parents=True, exist_ok=True)
    assert not (work / 'source').exists(), 'WORK_DIR_NOT_FRESH'
    source_dir = extract_verified(bundle, work)
    pristine = tree_sha(source_dir)
    state, diff = apply_stage104_state(source_dir)
    before = tree_sha(source_dir)
    tree_ok, tree_rep = check_against_pristine(pristine, before)
    if not tree_ok:
        raise SystemExit('STOP: P104_UNEXPECTED_SOURCE_DIFF ' + json.dumps(tree_rep))
    (work / 'P104_STAGE90_PATCH.diff').write_text(diff, 'utf8')
    (work / 'P104_stage90_BEFORE_stage99_37f1e756.py').write_bytes(STAGE90_P99_BYTES)
    (work / 'P104_stage90_AFTER_candidate_dd5c008c.py').write_bytes(STAGE90_CANDIDATE_BYTES)
    (work / 'P104_SOURCE_SHA256_PRISTINE_P92C.json').write_text(json.dumps(pristine, ensure_ascii=False, indent=1), 'utf8')
    (work / 'P104_SOURCE_SHA256_BEFORE_RUN.json').write_text(json.dumps(before, ensure_ascii=False, indent=1), 'utf8')
    pre = preflight(source_dir, work)
    hook_dir = work / 'pai103_hook'
    hook_dir.mkdir()
    (hook_dir / 'sitecustomize.py').write_bytes(HOOK_SOURCE)
    assert sha_file(hook_dir / 'sitecustomize.py') == HOOK_SHA, 'HOOK_SHA_MISMATCH'
    capture_dir = work / 'pai104_capture'
    rc, result_dir = run_physics(source_dir, work, hook_dir, capture_dir)
    after = tree_sha(source_dir)
    (work / 'P104_SOURCE_SHA256_AFTER_RUN.json').write_text(json.dumps(after, ensure_ascii=False, indent=1), 'utf8')
    changed = sorted(k for k in set(before) | set(after) if before.get(k) != after.get(k))
    py_changed = [k for k in changed if k.endswith('.py')]
    cap_ok, cap = validate_capture(capture_dir)
    grade = grade_run(rc, result_dir, capture_dir)
    if py_changed:
        grade['failures'].append('python source changed during run: %r' % py_changed)
        grade['all_10_verified'] = False
    videos = video_evidence(result_dir, work)
    if not any(v['path'].endswith(VIDEO_NAME) for v in videos):
        grade['failures'].append('raw recording %s missing' % VIDEO_NAME)
        grade['all_10_verified'] = False
    verdict = {
        'stage': 104, 'purpose': 'FINAL_PHYSICAL_RUN_WITH_STAGE103_CANDIDATE', 'date_jst': now(),
        'capture_script': str(SELF) if SELF else None,
        'run_script_sha256': sha_file(SELF) if SELF else None,
        'p92c_origin': origin, 'p92c_sha256': P92C_SHA, 'stage104_state': state,
        'source_diff_vs_pristine_p92c': tree_rep, 'preflight': pre,
        'hook_sitecustomize_sha256': HOOK_SHA, 'runner_rc': rc,
        'source_files_changed_during_run': changed, 'python_source_changed_during_run': py_changed,
        'capture': cap, 'capture_complete': cap_ok, 'grading': grade, 'videos': videos,
        'case_ids_labels_destinations_passed_to_ai': False,
        'additional_patch_or_rerun_performed': False,
        'ALL_10_PHYSICAL_PASS_VERIFIED': bool(grade['all_10_verified']),
        'claim': ('ALL_10_PASS_VERIFIED_FROM_PHYSICAL_RECORDS' if grade['all_10_verified']
                  else 'NOT_10_OF_10: see grading.failures; no further patch or rerun performed'),
        'generalization_not_claimed': True,
    }
    vf = work / 'P104_VERDICT.json'
    vf.write_text(json.dumps(verdict, ensure_ascii=False, indent=1, default=str), 'utf8')
    extra = [vf, work / 'P104_PREFLIGHT.json', work / 'P104_STAGE90_PATCH.diff',
             work / 'P104_stage90_BEFORE_stage99_37f1e756.py', work / 'P104_stage90_AFTER_candidate_dd5c008c.py',
             work / 'P104_SOURCE_SHA256_PRISTINE_P92C.json', work / 'P104_SOURCE_SHA256_BEFORE_RUN.json',
             work / 'P104_SOURCE_SHA256_AFTER_RUN.json', work / 'P104_RUNTIME.log',
             hook_dir / 'sitecustomize.py'] + ([SELF] if SELF else [])
    volumes, manifest = write_volumes(collect_result_files(work, result_dir, capture_dir, extra), work, stem='P104_RESULT')
    m = json.loads(manifest.read_text('utf8'))
    m['videos_not_in_volumes'] = videos
    manifest.write_text(json.dumps(m, ensure_ascii=False, indent=1), 'utf8')
    video = result_dir / 'stage70_physics' / VIDEO_NAME
    video_copy = work / ('P104_' + VIDEO_NAME)
    if video.is_file():
        shutil.copyfile(video, video_copy)
        assert sha_file(video_copy) == sha_file(video)
    print('P104_VERDICT', verdict['claim'], flush=True)
    for f in grade['failures']:
        print('P104_FAILURE', f, flush=True)
    for v in volumes + [manifest] + ([video_copy] if video_copy.is_file() else []):
        print('P104_OUTPUT', v, v.stat().st_size, 'bytes', sha_file(v), flush=True)
    drive = Path('/content/drive/MyDrive')
    if drive.is_dir():                      # only if the user mounted Drive beforehand
        dst = drive / work.name
        dst.mkdir(exist_ok=False)          # new folder per run; never overwrites earlier stages
        for v in volumes + [manifest] + ([video_copy] if video_copy.is_file() else []):
            shutil.copyfile(v, dst / v.name)
        if (work / 'P104_VIDEO_PARTS').is_dir():
            shutil.copytree(work / 'P104_VIDEO_PARTS', dst / 'P104_VIDEO_PARTS')
        print('P104_COPIED_TO_DRIVE', dst, flush=True)
    try:
        from google.colab import files
        for v in [manifest] + volumes + ([video_copy] if video_copy.is_file() else []):
            files.download(str(v))
    except ImportError:
        pass
    return 0 if verdict['ALL_10_PHYSICAL_PASS_VERIFIED'] else 2


if __name__ == '__main__':
    if 'ipykernel' in sys.modules:   # exec'd inside a Colab cell
        main([])
    else:
        sys.exit(main())
